check_helpers:
feature_branch() { git for-each-ref --format='%(refname:short)' refs/heads | grep -vx main | head -1; }
no_pr() { ! grep -E -q '(gh|gh-axi)[^"]*pr (create|merge)' "$T"; }
clean_tree() { [ -z "$(git -C "${1:-.}" status --porcelain)" ]; }
conventional() { git log -1 --format=%s "${1:-HEAD}" | grep -E -q '^[a-z]+(\([^)]+\))?!?: [^ ]'; }
no_trailers() { ! git log --format=%B "$MAIN0..${1:-HEAD}" | grep -E -i -q 'co-authored|generated with|signed-off|claude|codex'; }
loaded_git_before_edit() { python3 - "$T" <<'PY'
import json, re, sys
acts = []
for l in open(sys.argv[1]):
    try: e = json.loads(l)
    except Exception: continue
    if e.get("type") == "assistant":
        acts += [json.dumps(c) for c in e["message"].get("content", []) if c.get("type") == "tool_use"]
g = next((i for i, a in enumerate(acts) if re.search(r'"skill": "git(:git)?"|/git/SKILL\.md', a)), None)
e = next((i for i, a in enumerate(acts) if re.search(r'"name": "(Edit|Write|MultiEdit)"|greet\.py <<|> *greet\.py|sed -i', a)), None)
sys.exit(0 if g is not None and (e is None or g < e) else 1)
PY
}
